#[derive(Debug, Clone, PartialEq)]
pub enum TokenKind {
    // Literals
    Number(f64),
    Str(String),
    Identifier(String),
    // Keywords
    And, Class, Else, False, Fn, For, If, Nil, Or,
    Print, Return, Super, This, True, Var, While,
    // Operators
    Plus, Minus, Star, Slash,
    Equal, EqualEqual,
    Bang, BangEqual,
    Less, LessEqual,
    Greater, GreaterEqual,
    // Delimiters
    LeftParen, RightParen, LeftBrace, RightBrace,
    Comma, Dot, Semicolon,
    // Special
    Eof,
}

#[derive(Debug, Clone)]
pub struct Token {
    pub kind: TokenKind,
    pub line: usize,
}

pub struct Lexer {
    source: Vec<char>,
    start: usize,
    current: usize,
    line: usize,
    tokens: Vec<Token>,
}

impl Lexer {
    pub fn new(source: &str) -> Self {
        Lexer {
            source: source.chars().collect(),
            start: 0,
            current: 0,
            line: 1,
            tokens: Vec::new(),
        }
    }

    pub fn tokenize(&mut self) -> Result<Vec<Token>, String> {
        while !self.is_at_end() {
            self.start = self.current;
            self.scan_token()?;
        }
        self.tokens.push(Token { kind: TokenKind::Eof, line: self.line });
        Ok(self.tokens.clone())
    }

    fn scan_token(&mut self) -> Result<(), String> {
        let c = self.advance();
        match c {
            '(' => self.add_token(TokenKind::LeftParen),
            ')' => self.add_token(TokenKind::RightParen),
            '{' => self.add_token(TokenKind::LeftBrace),
            '}' => self.add_token(TokenKind::RightBrace),
            ',' => self.add_token(TokenKind::Comma),
            '.' => self.add_token(TokenKind::Dot),
            ';' => self.add_token(TokenKind::Semicolon),
            '+' => self.add_token(TokenKind::Plus),
            '-' => self.add_token(TokenKind::Minus),
            '*' => self.add_token(TokenKind::Star),
            '/' => {
                if self.match_char('/') {
                    while self.peek() != '\
' && !self.is_at_end() { self.advance(); }
                } else {
                    self.add_token(TokenKind::Slash);
                }
            }
            '=' => {
                if self.match_char('=') { self.add_token(TokenKind::EqualEqual); }
                else { self.add_token(TokenKind::Equal); }
            }
            '!' => {
                if self.match_char('=') { self.add_token(TokenKind::BangEqual); }
                else { self.add_token(TokenKind::Bang); }
            }
            '<' => {
                if self.match_char('=') { self.add_token(TokenKind::LessEqual); }
                else { self.add_token(TokenKind::Less); }
            }
            '>' => {
                if self.match_char('=') { self.add_token(TokenKind::GreaterEqual); }
                else { self.add_token(TokenKind::Greater); }
            }
            '"' => self.string(),
            c if c.is_ascii_digit() => self.number(),
            c if c.is_alphabetic() || c == '_' => self.identifier(),
            ' ' | '\' | '\	' => {},
            '\
' => self.line += 1,
            _ => return Err(format!("Unexpected character '{}' at line {}", c, self.line)),
        }
        Ok(())
    }

    // TODO: implement string(), number(), identifier() methods
    fn string(&mut self) { todo!("parse string literal") }
    fn number(&mut self) { todo!("parse number literal") }
    fn identifier(&mut self) { todo!("parse identifier or keyword") }

    fn advance(&mut self) -> char {
        let c = self.source[self.current];
        self.current += 1;
        c
    }

    fn peek(&self) -> char {
        if self.is_at_end() { '\0' } else { self.source[self.current] }
    }

    fn match_char(&mut self, expected: char) -> bool {
        if self.is_at_end() || self.source[self.current] != expected { return false; }
        self.current += 1;
        true
    }

    fn is_at_end(&self) -> bool {
        self.current >= self.source.len()
    }

    fn add_token(&mut self, kind: TokenKind) {
        self.tokens.push(Token { kind, line: self.line });
    }
}

mod lexer;
use lexer::Lexer;
use std::env;
use std::fs;

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() < 2 {
        eprintln!("usage: lox <file>");
        return;
    }
    let source = fs::read_to_string(&args[1]).expect("Failed to read file");
    let mut lexer = Lexer::new(&source);
    match lexer.tokenize() {
        Ok(tokens) => {
            for token in &tokens {
                println!("{:?}", token.kind);
            }
        }
        Err(e) => eprintln!("Lexer error: {}", e),
    }
}

