use my_interpreter::lexer::{Lexer, TokenKind};

#[test]
fn test_numbers() {
    let mut lexer = Lexer::new("42 3.14");
    let tokens = lexer.tokenize().unwrap();
    assert!(matches!(tokens[0].kind, TokenKind::Number(n) if (n - 42.0).abs() < f64::EPSILON));
    assert!(matches!(tokens[1].kind, TokenKind::Number(n) if (n - 3.14).abs() < f64::EPSILON));
}

#[test]
fn test_string_literal() {
    let mut lexer = Lexer::new("\"hello\"");
    let tokens = lexer.tokenize().unwrap();
    assert!(matches!(&tokens[0].kind, TokenKind::Str(s) if s == "hello"));
}

#[test]
fn test_keywords() {
    let mut lexer = Lexer::new("if else fn let return");
    let tokens = lexer.tokenize().unwrap();
    assert!(matches!(tokens[0].kind, TokenKind::If));
    assert!(matches!(tokens[1].kind, TokenKind::Else));
    assert!(matches!(tokens[2].kind, TokenKind::Fn));
    assert!(matches!(tokens[3].kind, TokenKind::Var));
    assert!(matches!(tokens[4].kind, TokenKind::Return));
}

#[test]
fn test_operators() {
    let mut lexer = Lexer::new("+ - * / == != <= >=");
    let tokens = lexer.tokenize().unwrap();
    assert!(matches!(tokens[0].kind, TokenKind::Plus));
    assert!(matches!(tokens[1].kind, TokenKind::Minus));
    assert!(matches!(tokens[2].kind, TokenKind::Star));
    assert!(matches!(tokens[3].kind, TokenKind::Slash));
    assert!(matches!(tokens[4].kind, TokenKind::EqualEqual));
    assert!(matches!(tokens[5].kind, TokenKind::BangEqual));
    assert!(matches!(tokens[6].kind, TokenKind::LessEqual));
    assert!(matches!(tokens[7].kind, TokenKind::GreaterEqual));
}

