use std::collections::HashMap;

#[derive(Debug, Clone, PartialEq)]
pub enum TokenKind {
    Number(f64),
    Str(String),
    Identifier(String),
    And, Class, Else, False, Fn, For, If, Nil, Or,
    Print, Return, Super, This, True, Var, While,
    Plus, Minus, Star, Slash,
    Equal, EqualEqual, Bang, BangEqual,
    Less, LessEqual, Greater, GreaterEqual,
    LeftParen, RightParen, LeftBrace, RightBrace,
    Comma, Dot, Semicolon, Eof,
}

#[derive(Debug, Clone)]
pub struct Token {
    pub kind: TokenKind,
    pub line: usize,
}

pub struct Lexer {
    source: Vec<char>,
    start: usize,
    current: usize,
    line: usize,
    tokens: Vec<Token>,
}

fn keywords() -> HashMap<&'static str, TokenKind> {
    let mut m = HashMap::new();
    m.insert("and", TokenKind::And);
    m.insert("class", TokenKind::Class);
    m.insert("else", TokenKind::Else);
    m.insert("false", TokenKind::False);
    m.insert("fn", TokenKind::Fn);
    m.insert("for", TokenKind::For);
    m.insert("if", TokenKind::If);
    m.insert("nil", TokenKind::Nil);
    m.insert("or", TokenKind::Or);
    m.insert("print", TokenKind::Print);
    m.insert("return", TokenKind::Return);
    m.insert("super", TokenKind::Super);
    m.insert("this", TokenKind::This);
    m.insert("true", TokenKind::True);
    m.insert("var", TokenKind::Var);
    m.insert("while", TokenKind::While);
    m
}

impl Lexer {
    pub fn new(source: &str) -> Self {
        Lexer {
            source: source.chars().collect(),
            start: 0,
            current: 0,
            line: 1,
            tokens: Vec::new(),
        }
    }

    pub fn tokenize(&mut self) -> Result<Vec<Token>, String> {
        while !self.is_at_end() {
            self.start = self.current;
            self.scan_token()?;
        }
        self.tokens.push(Token { kind: TokenKind::Eof, line: self.line });
        Ok(self.tokens.clone())
    }

    fn scan_token(&mut self) -> Result<(), String> {
        let c = self.advance();
        match c {
            '(' => self.add_token(TokenKind::LeftParen),
            ')' => self.add_token(TokenKind::RightParen),
            '{' => self.add_token(TokenKind::LeftBrace),
            '}' => self.add_token(TokenKind::RightBrace),
            ',' => self.add_token(TokenKind::Comma),
            '.' => self.add_token(TokenKind::Dot),
            ';' => self.add_token(TokenKind::Semicolon),
            '+' => self.add_token(TokenKind::Plus),
            '-' => self.add_token(TokenKind::Minus),
            '*' => self.add_token(TokenKind::Star),
            '/' => {
                if self.match_char('/') {
                    while self.peek() != '\
' && !self.is_at_end() { self.advance(); }
                } else {
                    self.add_token(TokenKind::Slash);
                }
            }
            '=' => { if self.match_char('=') { self.add_token(TokenKind::EqualEqual); } else { self.add_token(TokenKind::Equal); } }
            '!' => { if self.match_char('=') { self.add_token(TokenKind::BangEqual); } else { self.add_token(TokenKind::Bang); } }
            '<' => { if self.match_char('=') { self.add_token(TokenKind::LessEqual); } else { self.add_token(TokenKind::Less); } }
            '>' => { if self.match_char('=') { self.add_token(TokenKind::GreaterEqual); } else { self.add_token(TokenKind::Greater); } }
            '"' => self.string(),
            c if c.is_ascii_digit() => self.number(),
            c if c.is_alphabetic() || c == '_' => self.identifier(),
            ' ' | '\' | '\	' => {},
            '\
' => self.line += 1,
            _ => return Err(format!("Unexpected character '{}' at line {}", c, self.line)),
        }
        Ok(())
    }

    fn string(&mut self) {
        let mut value = String::new();
        while self.peek() != '"' && !self.is_at_end() {
            if self.peek() == '\
' { self.line += 1; }
            if self.peek() == '\\' { self.advance(); }
            value.push(self.advance());
        }
        if self.is_at_end() { return; }
        self.advance(); // closing quote
        self.add_token(TokenKind::Str(value));
    }

    fn number(&mut self) {
        while self.peek().is_ascii_digit() { self.advance(); }
        if self.peek() == '.' && self.peek_next().is_ascii_digit() {
            self.advance();
            while self.peek().is_ascii_digit() { self.advance(); }
        }
        let text: String = self.source[self.start..self.current].iter().collect();
        self.add_token(TokenKind::Number(text.parse().unwrap()));
    }

    fn identifier(&mut self) {
        while self.peek().is_alphanumeric() || self.peek() == '_' { self.advance(); }
        let text: String = self.source[self.start..self.current].iter().collect();
        let kws = keywords();
        let kind = kws.get(text.as_str()).cloned().unwrap_or(TokenKind::Identifier(text));
        self.add_token(kind);
    }

    fn advance(&mut self) -> char {
        let c = self.source[self.current];
        self.current += 1;
        c
    }

    fn peek(&self) -> char {
        if self.is_at_end() { '\0' } else { self.source[self.current] }
    }

    fn peek_next(&self) -> char {
        if self.current + 1 >= self.source.len() { '\0' } else { self.source[self.current + 1] }
    }

    fn match_char(&mut self, expected: char) -> bool {
        if self.is_at_end() || self.source[self.current] != expected { return false; }
        self.current += 1;
        true
    }

    fn is_at_end(&self) -> bool {
        self.current >= self.source.len()
    }

    fn add_token(&mut self, kind: TokenKind) {
        self.tokens.push(Token { kind, line: self.line });
    }
}

