use crate::ast::{Expr, Stmt, BinOp, UnaryOp};
use crate::lexer::{Token, TokenKind};

pub struct Parser {
    tokens: Vec<Token>,
    pos: usize,
}

impl Parser {
    pub fn new(tokens: Vec<Token>) -> Self {
        Parser { tokens, pos: 0 }
    }

    pub fn parse_program(&mut self) -> Result<Vec<Stmt>, String> {
        let mut stmts = Vec::new();
        while !self.check(&TokenKind::Eof) {
            stmts.push(self.statement()?);
        }
        Ok(stmts)
    }

    fn statement(&mut self) -> Result<Stmt, String> {
        if self.match_token(&TokenKind::Print) {
            let expr = self.expression()?;
            self.consume(&TokenKind::Semicolon, "Expected ';' after print")?;
            return Ok(Stmt::Print(expr));
        }
        if self.match_token(&TokenKind::Var) {
            let name = self.consume_identifier()?;
            let init = if self.match_token(&TokenKind::Equal) {
                self.expression()?
            } else {
                Expr::Nil
            };
            self.consume(&TokenKind::Semicolon, "Expected ';' after var declaration")?;
            return Ok(Stmt::Var { name, init });
        }
        // TODO: handle block, if, while, func, return, expression statements
        let expr = self.expression()?;
        self.consume(&TokenKind::Semicolon, "Expected ';' after expression")?;
        Ok(Stmt::Expr(expr))
    }

    fn expression(&mut self) -> Result<Expr, String> {
        // TODO: implement expression parsing (precedence climbing)
        // Start with equality, then comparison, addition, multiplication,
        // unary, primary
        todo!("parse expressions")
    }

    // Helper methods
    fn match_token(&mut self, kind: &TokenKind) -> bool {
        if self.check(kind) { self.pos += 1; true } else { false }
    }
    fn check(&self, kind: &TokenKind) -> bool {
        self.peek().map_or(false, |t| std::mem::discriminant(&t.kind) == std::mem::discriminant(kind))
    }
    fn peek(&self) -> Option<&Token> { self.tokens.get(self.pos) }
    fn advance(&mut self) -> &Token { let t = &self.tokens[self.pos]; self.pos += 1; t }
    fn consume(&mut self, kind: &TokenKind, msg: &str) -> Result<(), String> {
        if self.match_token(kind) { Ok(()) } else { Err(msg.to_string()) }
    }
    fn consume_identifier(&mut self) -> Result<String, String> {
        match &self.peek().map(|t| &t.kind) {
            Some(TokenKind::Identifier(name)) => { let n = name.clone(); self.pos += 1; Ok(n) }
            _ => Err("Expected identifier".to_string()),
        }
    }
}

