use crate::ast::{Expr, Stmt, BinOp, UnaryOp};
use crate::lexer::{Token, TokenKind};

pub struct Parser {
    tokens: Vec<Token>,
    pos: usize,
}

impl Parser {
    pub fn new(tokens: Vec<Token>) -> Self { Parser { tokens, pos: 0 } }
    pub fn parse_program(&mut self) -> Result<Vec<Stmt>, String> {
        let mut stmts = Vec::new();
        while !self.check(&TokenKind::Eof) { stmts.push(self.statement()?); }
        Ok(stmts)
    }
    fn statement(&mut self) -> Result<Stmt, String> {
        if self.match_token(&TokenKind::Print) {
            let expr = self.expression()?;
            self.consume(&TokenKind::Semicolon, "Expected ';'")?;
            return Ok(Stmt::Print(expr));
        }
        if self.match_token(&TokenKind::Var) {
            let name = self.consume_identifier()?;
            let init = if self.match_token(&TokenKind::Equal) { self.expression()? } else { Expr::Nil };
            self.consume(&TokenKind::Semicolon, "Expected ';'")?;
            return Ok(Stmt::Var { name, init });
        }
        if self.match_token(&TokenKind::LeftBrace) {
            let mut stmts = Vec::new();
            while !self.check(&TokenKind::RightBrace) && !self.check(&TokenKind::Eof) {
                stmts.push(self.statement()?);
            }
            self.consume(&TokenKind::RightBrace, "Expected '}'")?;
            return Ok(Stmt::Block(stmts));
        }
        let expr = self.expression()?;
        self.consume(&TokenKind::Semicolon, "Expected ';'")?;
        Ok(Stmt::Expr(expr))
    }
    fn expression(&mut self) -> Result<Expr, String> { self.or() }
    fn or(&mut self) -> Result<Expr, String> {
        let mut left = self.and()?;
        while self.match_token(&TokenKind::Or) {
            let right = self.and()?;
            left = Expr::Binary { op: BinOp::Or, left: Box::new(left), right: Box::new(right) };
        }
        Ok(left)
    }
    fn and(&mut self) -> Result<Expr, String> {
        let mut left = self.equality()?;
        while self.match_token(&TokenKind::And) {
            let right = self.equality()?;
            left = Expr::Binary { op: BinOp::And, left: Box::new(left), right: Box::new(right) };
        }
        Ok(left)
    }
    fn equality(&mut self) -> Result<Expr, String> {
        let mut left = self.comparison()?;
        loop {
            if self.match_token(&TokenKind::EqualEqual) { let r = self.comparison()?; left = Expr::Binary { op: BinOp::Eq, left: Box::new(left), right: Box::new(r) }; }
            else if self.match_token(&TokenKind::BangEqual) { let r = self.comparison()?; left = Expr::Binary { op: BinOp::Neq, left: Box::new(left), right: Box::new(r) }; }
            else { break; }
        }
        Ok(left)
    }
    fn comparison(&mut self) -> Result<Expr, String> {
        let mut left = self.term()?;
        loop {
            if self.match_token(&TokenKind::Less) { let r = self.term()?; left = Expr::Binary { op: BinOp::Lt, left: Box::new(left), right: Box::new(r) }; }
            else if self.match_token(&TokenKind::LessEqual) { let r = self.term()?; left = Expr::Binary { op: BinOp::Lte, left: Box::new(left), right: Box::new(r) }; }
            else if self.match_token(&TokenKind::Greater) { let r = self.term()?; left = Expr::Binary { op: BinOp::Gt, left: Box::new(left), right: Box::new(r) }; }
            else if self.match_token(&TokenKind::GreaterEqual) { let r = self.term()?; left = Expr::Binary { op: BinOp::Gte, left: Box::new(left), right: Box::new(r) }; }
            else { break; }
        }
        Ok(left)
    }
    fn term(&mut self) -> Result<Expr, String> {
        let mut left = self.factor()?;
        loop {
            if self.match_token(&TokenKind::Plus) { let r = self.factor()?; left = Expr::Binary { op: BinOp::Add, left: Box::new(left), right: Box::new(r) }; }
            else if self.match_token(&TokenKind::Minus) { let r = self.factor()?; left = Expr::Binary { op: BinOp::Sub, left: Box::new(left), right: Box::new(r) }; }
            else { break; }
        }
        Ok(left)
    }
    fn factor(&mut self) -> Result<Expr, String> {
        let mut left = self.unary()?;
        loop {
            if self.match_token(&TokenKind::Star) { let r = self.unary()?; left = Expr::Binary { op: BinOp::Mul, left: Box::new(left), right: Box::new(r) }; }
            else if self.match_token(&TokenKind::Slash) { let r = self.unary()?; left = Expr::Binary { op: BinOp::Div, left: Box::new(left), right: Box::new(r) }; }
            else { break; }
        }
        Ok(left)
    }
    fn unary(&mut self) -> Result<Expr, String> {
        if self.match_token(&TokenKind::Minus) { let e = self.unary()?; return Ok(Expr::Unary { op: UnaryOp::Neg, expr: Box::new(e) }); }
        if self.match_token(&TokenKind::Bang) { let e = self.unary()?; return Ok(Expr::Unary { op: UnaryOp::Not, expr: Box::new(e) }); }
        self.primary()
    }
    fn primary(&mut self) -> Result<Expr, String> {
        let token = self.advance();
        match &token.kind {
            TokenKind::Number(n) => Ok(Expr::Number(*n)),
            TokenKind::Str(s) => Ok(Expr::Str(s.clone())),
            TokenKind::True => Ok(Expr::Bool(true)),
            TokenKind::False => Ok(Expr::Bool(false)),
            TokenKind::Nil => Ok(Expr::Nil),
            TokenKind::Identifier(name) => Ok(Expr::Ident(name.clone())),
            TokenKind::LeftParen => {
                let e = self.expression()?;
                self.consume(&TokenKind::RightParen, "Expected ')' after expression")?;
                Ok(e)
            }
            _ => Err(format!("Unexpected token {:?}", token.kind)),
        }
    }
    fn match_token(&mut self, kind: &TokenKind) -> bool { if self.check(kind) { self.pos += 1; true } else { false } }
    fn check(&self, kind: &TokenKind) -> bool { self.peek().map_or(false, |t| std::mem::discriminant(&t.kind) == std::mem::discriminant(kind)) }
    fn peek(&self) -> Option<&Token> { self.tokens.get(self.pos) }
    fn advance(&mut self) -> &Token { let t = &self.tokens[self.pos]; self.pos += 1; t }
    fn consume(&mut self, kind: &TokenKind, msg: &str) -> Result<(), String> { if self.match_token(kind) { Ok(()) } else { Err(msg.to_string()) } }
    fn consume_identifier(&mut self) -> Result<String, String> {
        match &self.peek().map(|t| &t.kind) {
            Some(TokenKind::Identifier(name)) => { let n = name.clone(); self.pos += 1; Ok(n) }
            _ => Err("Expected identifier".to_string()),
        }
    }
}

