#[derive(Debug, Clone, PartialEq)]
pub enum Value {
    Number(f64),
    Str(String),
    Bool(bool),
    Nil,
    Void,
}

impl std::fmt::Display for Value {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Value::Number(n) => write!(f, "{}", n),
            Value::Str(s) => write!(f, "{}", s),
            Value::Bool(b) => write!(f, "{}", b),
            Value::Nil => write!(f, "nil"),
            Value::Void => write!(f, "void"),
        }
    }
}

pub struct Interpreter {
    env: HashMap<String, Value>,
}

impl Interpreter {
    pub fn new() -> Self { Interpreter { env: HashMap::new() } }
    pub fn run(&mut self, program: &[Stmt]) -> Result<(), String> {
        for stmt in program { self.exec_stmt(stmt)?; }
        Ok(())
    }
    fn exec_stmt(&mut self, stmt: &Stmt) -> Result<(), String> {
        match stmt {
            Stmt::Expr(e) => { self.eval_expr(e)?; Ok(()) }
            Stmt::Print(e) => { let v = self.eval_expr(e)?; println!("{}", v); Ok(()) }
            Stmt::Var { name, init } => { let v = self.eval_expr(init)?; self.env.insert(name.clone(), v); Ok(()) }
            Stmt::Block(stmts) => {
                let old = self.env.clone();
                for s in stmts { self.exec_stmt(s)?; }
                self.env = old;
                Ok(())
            }
            Stmt::If { condition, then_branch, else_branch } => {
                if self.eval_expr(condition)?.is_truthy() { self.exec_stmt(then_branch)?; }
                else if let Some(else_b) = else_branch { self.exec_stmt(else_b)?; }
                Ok(())
            }
            Stmt::While { condition, body } => {
                while self.eval_expr(condition)?.is_truthy() { self.exec_stmt(body)?; }
                Ok(())
            }
            _ => Ok(()),
        }
    }
    fn eval_expr(&mut self, expr: &Expr) -> Result<Value, String> {
        match expr {
            Expr::Number(n) => Ok(Value::Number(*n)),
            Expr::Str(s) => Ok(Value::Str(s.clone())),
            Expr::Bool(b) => Ok(Value::Bool(*b)),
            Expr::Nil => Ok(Value::Nil),
            Expr::Ident(name) => self.env.get(name).cloned().ok_or_else(|| format!("Undefined variable '{}'", name)),
            Expr::Unary { op, expr } => {
                let v = self.eval_expr(expr)?;
                match op {
                    UnaryOp::Neg => match v { Value::Number(n) => Ok(Value::Number(-n)), _ => Err("Operand must be a number".to_string()) },
                    UnaryOp::Not => Ok(Value::Bool(!v.is_truthy())),
                }
            }
            Expr::Binary { op, left, right } => {
                let l = self.eval_expr(left)?;
                let r = self.eval_expr(right)?;
                match op {
                    BinOp::Add => match (&l, &r) {
                        (Value::Number(a), Value::Number(b)) => Ok(Value::Number(a + b)),
                        (Value::Str(a), Value::Str(b)) => Ok(Value::Str(format!("{}{}", a, b))),
                        _ => Err("Operands must be two numbers or two strings".to_string()),
                    },
                    BinOp::Sub => Ok(Value::Number(l.to_f64()? - r.to_f64()?)),
                    BinOp::Mul => Ok(Value::Number(l.to_f64()? * r.to_f64()?)),
                    BinOp::Div => Ok(Value::Number(l.to_f64()? / r.to_f64()?)),
                    BinOp::Eq => Ok(Value::Bool(l == r)),
                    BinOp::Neq => Ok(Value::Bool(l != r)),
                    BinOp::Lt => Ok(Value::Bool(l.to_f64()? < r.to_f64()?)),
                    BinOp::Lte => Ok(Value::Bool(l.to_f64()? <= r.to_f64()?)),
                    BinOp::Gt => Ok(Value::Bool(l.to_f64()? > r.to_f64()?)),
                    BinOp::Gte => Ok(Value::Bool(l.to_f64()? >= r.to_f64()?)),
                    BinOp::And => Ok(Value::Bool(l.is_truthy() && r.is_truthy())),
                    BinOp::Or => Ok(Value::Bool(l.is_truthy() || r.is_truthy())),
                }
            }
            Expr::Call { .. } => Err("Function calls not yet supported".to_string()),
        }
    }
}

