    fn is_truthy(&self) -> bool {
        !matches!(self, Value::Nil | Value::Bool(false))
    }
    fn to_f64(&self) -> Result<f64, String> {
        match self { Value::Number(n) => Ok(*n), _ => Err("Operand must be a number".to_string()) }
    }
}

