use crate::ast::{Expr, Stmt, BinOp, UnaryOp};
use std::collections::HashMap;

#[derive(Debug, Clone, PartialEq)]
pub enum Value {
    Number(f64),
    Str(String),
    Bool(bool),
    Nil,
    Void,
    Func(LoxFunction),
}

impl Value {
    fn is_truthy(&self) -> bool { !matches!(self, Value::Nil | Value::Bool(false)) }
    fn to_f64(&self) -> Result<f64, String> { match self { Value::Number(n) => Ok(*n), _ => Err("Must be number".to_string()) } }
    fn display(&self) -> String {
        match self {
            Value::Number(n) => format!("{}", n),
            Value::Str(s) => s.clone(),
            Value::Bool(b) => format!("{}", b),
            Value::Nil => "nil".to_string(),
            Value::Void => "void".to_string(),
            Value::Func(f) => format!("<fn {}>", f.name),
        }
    }
}

#[derive(Debug, Clone)]
pub struct LoxFunction {
    pub name: String,
    pub params: Vec<String>,
    pub body: Box<Stmt>,
    pub closure: Environment,
}

#[derive(Debug, Clone)]
pub struct Environment {
    scopes: Vec<HashMap<String, Value>>,
}

impl Environment {
    pub fn new() -> Self { Environment { scopes: vec![HashMap::new()] } }
    pub fn define(&mut self, name: String, value: Value) { self.scopes.last_mut().unwrap().insert(name, value); }
    pub fn get(&self, name: &str) -> Option<&Value> {
        for scope in self.scopes.iter().rev() { if let Some(v) = scope.get(name) { return Some(v); } }
        None
    }
    pub fn assign(&mut self, name: &str, value: Value) -> Result<(), String> {
        for scope in self.scopes.iter_mut().rev() {
            if scope.contains_key(name) { scope.insert(name.to_string(), value); return Ok(()); }
        }
        Err(format!("Undefined '{}'", name))
    }
    pub fn push_scope(&mut self) { self.scopes.push(HashMap::new()); }
    pub fn pop_scope(&mut self) { self.scopes.pop(); }
}

pub struct Interpreter { env: Environment }

enum ExecResult { Ok, Return(Value) }

impl Interpreter {
    pub fn new() -> Self { Interpreter { env: Environment::new() } }
    pub fn run(&mut self, program: &[Stmt]) -> Result<(), String> {
        for stmt in program { self.exec_stmt(stmt)?; } Ok(())
    }
    fn exec_stmt(&mut self, stmt: &Stmt) -> Result<ExecResult, String> {
        match stmt {
            Stmt::Expr(e) => { self.eval_expr(e)?; Ok(ExecResult::Ok) }
            Stmt::Print(e) => { println!("{}", self.eval_expr(e)?.display()); Ok(ExecResult::Ok) }
            Stmt::Var { name, init } => { let v = self.eval_expr(init)?; self.env.define(name.clone(), v); Ok(ExecResult::Ok) }
            Stmt::Block(stmts) => {
                self.env.push_scope();
                for s in stmts { if let ExecResult::Return(v) = self.exec_stmt(s)? { self.env.pop_scope(); return Ok(ExecResult::Return(v)); } }
                self.env.pop_scope();
                Ok(ExecResult::Ok)
            }
            Stmt::If { condition, then_branch, else_branch } => {
                if self.eval_expr(condition)?.is_truthy() { self.exec_stmt(then_branch)? } else if let Some(e) = else_branch { self.exec_stmt(e)? } else { ExecResult::Ok }
            }
            Stmt::While { condition, body } => {
                while self.eval_expr(condition)?.is_truthy() { if let ExecResult::Return(v) = self.exec_stmt(body)? { return Ok(ExecResult::Return(v)); } }
                Ok(ExecResult::Ok)
            }
            Stmt::Func { name, params, body } => {
                let func = LoxFunction { name: name.clone(), params: params.clone(), body: body.clone(), closure: self.env.clone() };
                self.env.define(name.clone(), Value::Func(func));
                Ok(ExecResult::Ok)
            }
            Stmt::Return(e) => { let v = self.eval_expr(e)?; Ok(ExecResult::Return(v)) }
        }
    }
    fn eval_expr(&mut self, expr: &Expr) -> Result<Value, String> {
        match expr {
            Expr::Number(n) => Ok(Value::Number(*n)),
            Expr::Str(s) => Ok(Value::Str(s.clone())),
            Expr::Bool(b) => Ok(Value::Bool(*b)),
            Expr::Nil => Ok(Value::Nil),
            Expr::Ident(name) => self.env.get(name).cloned().ok_or_else(|| format!("Undefined '{}'", name)),
            Expr::Unary { op, expr } => {
                let v = self.eval_expr(expr)?;
                match op { UnaryOp::Neg => Ok(Value::Number(-v.to_f64()?)), UnaryOp::Not => Ok(Value::Bool(!v.is_truthy())) }
            }
            Expr::Binary { op, left, right } => {
                let l = self.eval_expr(left)?;
                let r = self.eval_expr(right)?;
                match op {
                    BinOp::Add => match (&l, &r) {
                        (Value::Number(a), Value::Number(b)) => Ok(Value::Number(a + b)),
                        (Value::Str(a), Value::Str(b)) => Ok(Value::Str(format!("{}{}", a, b))),
                        _ => Err("Invalid operands".to_string()),
                    },
                    BinOp::Sub => Ok(Value::Number(l.to_f64()? - r.to_f64()?)),
                    BinOp::Mul => Ok(Value::Number(l.to_f64()? * r.to_f64()?)),
                    BinOp::Div => Ok(Value::Number(l.to_f64()? / r.to_f64()?)),
                    BinOp::Eq => Ok(Value::Bool(l == r)),
                    BinOp::Neq => Ok(Value::Bool(l != r)),
                    BinOp::Lt => Ok(Value::Bool(l.to_f64()? < r.to_f64()?)),
                    BinOp::Lte => Ok(Value::Bool(l.to_f64()? <= r.to_f64()?)),
                    BinOp::Gt => Ok(Value::Bool(l.to_f64()? > r.to_f64()?)),
                    BinOp::Gte => Ok(Value::Bool(l.to_f64()? >= r.to_f64()?)),
                    BinOp::And => Ok(Value::Bool(l.is_truthy() && r.is_truthy())),
                    BinOp::Or => Ok(Value::Bool(l.is_truthy() || r.is_truthy())),
                }
            }
            Expr::Call { callee, args } => {
                let func_val = self.eval_expr(callee)?;
                let arg_vals: Result<Vec<Value>, String> = args.iter().map(|a| self.eval_expr(a)).collect();
                let arg_vals = arg_vals?;
                match func_val {
                    Value::Func(func) => self.call_function(&func, arg_vals),
                    _ => Err("Can only call functions".to_string()),
                }
            }
        }
    }
    fn call_function(&mut self, func: &LoxFunction, args: Vec<Value>) -> Result<Value, String> {
        let mut env = func.closure.clone();
        env.push_scope();
        for (param, arg) in func.params.iter().zip(args) {
            env.define(param.clone(), arg);
        }
        let old_env = self.env.clone();
        self.env = env;
        let result = match self.exec_stmt(&func.body)? {
            ExecResult::Return(v) => v,
            ExecResult::Ok => Value::Void,
        };
        self.env = old_env;
        Ok(result)
    }
}
